import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 14 · Insurer and oracle","description":"","frontmatter":{},"headers":[],"relativePath":"modules/14-insurer.md","filePath":"modules/14-insurer.md","lastUpdated":1790431304000}'),r={name:"modules/14-insurer.md"};function n(o,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-14-·-insurer-and-oracle" tabindex="-1">Module 14 · Insurer and oracle <a class="header-anchor" href="#module-14-·-insurer-and-oracle" aria-label="Permalink to &quot;Module 14 · Insurer and oracle&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contracts</strong></td><td><code>RainOracle.sol</code>, <code>CropInsurance.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Insurer</td></tr><tr><td><strong>Pattern</strong></td><td>M-of-N oracle with on-chain median; parametric insurance</td></tr><tr><td><strong>Stamp</strong></td><td>Module 14 (awarded to the <strong>policyholder</strong> on purchase)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>A smart contract can see its own storage, its own balance, the block timestamp, and nothing else. It cannot see the weather, a share price, an election result, or whether a parcel arrived.</p><p>This is <strong>the oracle problem</strong>, and it is the boundary of what blockchains can do. Every other module in Trustville has brushed against it — module 4&#39;s origin string, module 7&#39;s issuer, module 13&#39;s arbiter — and this one confronts it directly.</p><p>Crop insurance makes it concrete. A farmer wants cover against drought. The payout depends on rainfall. Rainfall is a fact about the sky.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Two contracts, and the split matters.</p><p><strong><code>RainOracle</code></strong> answers one question: how much rain fell in period <em>N</em>? Several independent reporters submit a number, and once a quorum has reported, anyone may finalise: the contract takes the <strong>median</strong> and writes it down for ever.</p><p><strong><code>CropInsurance</code></strong> sells <strong>parametric</strong> cover. Not &quot;we will assess your loss&quot; but &quot;if the oracle&#39;s reading for period N is below the trigger, you receive your coverage amount&quot;. No adjuster, no claim form, no argument — and no attempt to measure your actual loss.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Oracle.</strong> A mechanism for getting off-chain facts on chain. Every oracle is a trust assumption with good manners.</p><p><strong>M-of-N reporting.</strong> N reporters, any M constitute a quorum. Here <code>MIN_QUORUM</code> is 2 and <code>MAX_REPORTS</code> is 9.</p><p><strong>Median, not mean.</strong> The middle value. One reporter who submits a wild number moves the mean a lot and the median not at all. This one choice is most of the oracle&#39;s robustness.</p><p><strong>Parametric insurance.</strong> Payout triggered by a measured index rather than an assessed loss. Real, widely used in agriculture and catastrophe cover, and it trades accuracy for speed and cheapness.</p><p><strong>Basis risk.</strong> The gap between the index and your actual loss. Your field floods while the gauge stays dry; you get nothing, and the policy worked exactly as written.</p><p><strong>Reserving.</strong> Setting aside the money to pay a promise at the moment the promise is made.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>period ends ─▸ reporters report ─▸ quorum reached ─▸ anyone finalises (median) ─▸ policies settle</span></span></code></pre></div><p><strong>Oracle</strong></p><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>report(period, mm)</code></td><td><code>REPORTER_ROLE</code></td><td>Only for a <strong>finished</strong> period, once each</td></tr><tr><td><code>finalize(period)</code></td><td><strong>anyone</strong></td><td>At or above quorum; computes the median</td></tr><tr><td><code>reading(period)</code></td><td>anyone</td><td><code>(finalized, mm, count)</code></td></tr><tr><td><code>reportsOf(period)</code></td><td>anyone</td><td>Every individual submission, and who made it</td></tr><tr><td><code>setQuorum(n)</code></td><td>admin</td><td>Between 2 and 9</td></tr></tbody></table><p><strong>Insurance</strong></p><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>fund(amount)</code></td><td>anyone</td><td>Adds to the pool</td></tr><tr><td><code>buy(period, coverage)</code></td><td>anyone</td><td>Only a period that has <strong>not begun</strong></td></tr><tr><td><code>settle(id)</code></td><td><strong>anyone</strong></td><td>Reads the oracle, pays or expires</td></tr><tr><td><code>available()</code></td><td>view</td><td>Held minus reserved</td></tr><tr><td><code>setTerms(trigger, premiumBps)</code></td><td>admin</td><td>New policies only</td></tr></tbody></table><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Nobody reports the future:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (period </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> currentPeriod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PeriodNotOver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>A reporter who could report a period still running — or one yet to start — could buy a policy and then write their own payout. The rule removes the possibility rather than trusting the reporter.</p><p><strong>Nobody insures the past:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (period </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> oracle.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">currentPeriod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PeriodAlreadyStarted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>The mirror image. Buying cover for a drought you already know happened is not insurance, it is a withdrawal. Together, these two lines mean a policy is always bought before the fact and reported after it, with no window where anyone knows both.</p><p><strong>The median is computed on a copy:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[](</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n; i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) a[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> values[i];</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// insertion sort on \`a\`</span></span></code></pre></div><p>Sorting the stored array in place would be cheaper — and would destroy the audit trail. <code>reportsOf</code> must keep returning who said what, in submission order, for ever. A reporter whose number sat far from the median is permanently visible, which is the accountability mechanism this design has instead of a penalty. Insertion sort is the right algorithm at n ≤ 9; the bound is what makes an on-chain sort defensible at all.</p><p><strong>One liar cannot move the answer.</strong> With reports of 10, 12 and 900, the median is 12. There is a test called <code>test_OneLiarCannotMoveTheAnswer</code> that says exactly this.</p><p><strong>A majority of reporters can move it to anything.</strong> With 10, 900 and 900, the median is 900. There is also a test called <code>test_AMajorityOfReportersControlsTheAnswer</code>, and it is the more important of the two. <strong>The oracle does not create truth; it makes corrupting the truth require a majority of a known set of parties.</strong> That is the entire security claim, stated honestly. Whether it is enough depends on who those parties are — which is a governance question, not a cryptographic one.</p><p><strong>An unreported period is not a drought:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> finalized, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mm,) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> oracle.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reading</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(p.period);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">finalized) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NoReadingYet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Solidity&#39;s default for an unset <code>uint32</code> is zero, and zero millimetres of rain is the most extreme drought possible. A settlement that read the raw value would pay out every policy for every period nobody bothered to report. The <code>finalized</code> flag exists so that &quot;no answer&quot; can never be mistaken for &quot;the worst possible answer&quot; — and <strong>this class of bug has drained real protocols.</strong> Whenever a contract reads a number from somewhere else, ask what the uninitialised value means.</p><p><strong>Coverage is reserved at sale, not at settlement:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> free </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> available</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// held − reserved</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (coverage </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> free) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NotEnoughInThePool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(free, coverage);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reserved </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> coverage;</span></span></code></pre></div><p>The insurer can never promise more than it holds. A real insurer does the opposite — it writes far more cover than its capital, on the actuarial bet that not everything pays at once, which is why insurers can fail. This contract cannot become insolvent, and the price of that is capital efficiency: to cover a thousand farmers you must hold every penny of a thousand payouts.</p><p>Fully-reserved versus fractionally-reserved is a real design axis, not a beginner&#39;s simplification. Know which one you are building.</p><p><strong>The trigger is frozen at purchase:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">triggerMm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> triggerMm,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// copied into the policy, not read at settlement</span></span></code></pre></div><p><code>setTerms</code> changes what <em>new</em> policies are sold at. A live policy keeps what it was sold with. An insurer who could raise the trigger after taking your premium is not selling insurance, and a contract that read the current value at settlement would be exactly that insurer.</p><p><strong>Settlement is a measurement, not a decision.</strong> Anyone may call <code>settle</code>, because the caller cannot influence the outcome — the reading is already fixed. A holder who has lost their phone still gets paid, by a stranger, for the cost of gas. Compare with modules 5, 10 and 13, where a human must judge: here the judgement was moved into the oracle, and the payment is arithmetic.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Read <code>currentPeriod()</code>. Buy cover for the <strong>next</strong> period.</li><li>Try to buy for the current one. <code>PeriodAlreadyStarted</code>.</li><li>Wait for the period to end.</li><li>Watch the three reporter services submit. <code>Reported</code> events, one per reporter.</li><li>Call <code>reportsOf(period)</code> and read the three numbers.</li><li><code>finalize(period)</code>. The median is written.</li><li><code>settle(id)</code> — from an account that is not the holder. Paid or expired, depending.</li></ol><p>Then break it:</p><ol start="8"><li>Run a reporter with <code>--lie</code> and see the median ignore it. Then check <code>reportsOf</code>: the lie is there for ever, next to its author&#39;s address.</li><li>Run <strong>two</strong> reporters with <code>--lie</code> out of three. Now the median is theirs.</li><li>Try to settle a period nobody reported. <code>NoReadingYet</code> — not a payout.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reported(period: 480123, reporter: 0x…, mm: 11, count: 1)</span></span>
<span class="line"><span>Reported(period: 480123, reporter: 0x…, mm: 13, count: 2)</span></span>
<span class="line"><span>Reported(period: 480123, reporter: 0x…, mm: 900, count: 3)</span></span>
<span class="line"><span>Finalized(period: 480123, mm: 13, count: 3, by: 0x…)</span></span>
<span class="line"><span>PolicySettled(id: 5, holder: 0x…, paid: false, mm: 13, amount: 0)</span></span></code></pre></div><p>Median of 11, 13 and 900 is 13. The 900 is preserved, attributable and permanent.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For crop insurance in a country with a functioning insurance market, the incumbent wins: it assesses actual loss, it is regulated, it is capitalised, and it can be sued.</p><p>Parametric cover on chain earns its place where <strong>conventional insurance does not reach</strong> — smallholders whose claims cost more to assess than to pay, regions with no adjusters — and where the <em>speed</em> matters: a payout hours after the reading, not months after a visit. Real programmes of exactly this kind exist and pay out to farmers today, mostly without a blockchain, which should tell you the parametric idea is doing more work than the ledger is.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>The oracle problem.</strong> It is reduced to &quot;trust a majority of these N&quot;, not eliminated.</li><li><strong>Basis risk.</strong> The index is not your loss. The most common complaint about real parametric products, and unfixable in principle.</li><li><strong>Reporter collusion.</strong> A majority decides the weather.</li><li><strong>Reporter apathy.</strong> No quorum, no reading, no settlement — policies simply hang.</li><li><strong>Where the number came from.</strong> A reporter&#39;s gauge could be broken, or simulated. In this repository it <em>is</em> simulated, and being clear about that is part of the lesson.</li><li><strong>Insurer insolvency by another route.</strong> Full reserving fixes the promise, not the admin&#39;s <code>withdrawSurplus</code>.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Treating an unset reading as data.</strong> The zero-drought bug above.</li><li><strong>Using the mean.</strong> One outlier, one wrong answer.</li><li><strong>Sorting the stored array.</strong> Cheaper, and it deletes the evidence.</li><li><strong>Reading the current trigger at settlement.</strong> Lets the insurer rewrite live policies.</li><li><strong>Letting reporters report the current period.</strong> Self-dealing.</li><li><strong>Unbounded report arrays.</strong> An on-chain sort with no cap is a gas bomb.</li><li><strong>Not reserving.</strong> The pool sells more cover than it holds and the last claimant finds it empty.</li><li><strong>A single reporter.</strong> Then you have an oracle with a single point of failure and a lot of extra code.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can a reporter report the current or a future period? Report twice?</li><li>[ ] Can a period be finalised below quorum? Finalised twice?</li><li>[ ] What does a settlement do when the oracle has no reading?</li><li>[ ] Can <code>reserved</code> ever exceed the token balance?</li><li>[ ] Can a policy be settled twice, or by someone other than the holder — and should either matter?</li><li>[ ] Does <code>setTerms</code> affect live policies?</li><li>[ ] Can the admin withdraw below <code>reserved</code>?</li><li>[ ] Who holds <code>REPORTER_ROLE</code>, how many are there, and who could grant themselves more?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Require reporters to stake, and slash anyone whose report sits far from the median. Then work out how a majority uses slashing to punish the one honest reporter.</li><li>Add a dispute window between finalisation and settlement, and decide who resolves it.</li><li>Weight the median by stake, and argue about whether that is an improvement or module 12&#39;s plutocracy in a lab coat.</li><li>Replace the simulated gauge with a real weather API in <code>services/rain-reporter</code>, and notice you have simply moved the trust to whoever runs that API.</li><li>Add fractional reserving with a solvency ratio, then simulate a year where every policy pays.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://chain.link/education-hub/oracle-problem" target="_blank" rel="noreferrer">Chainlink&#39;s oracle problem overview</a></li><li>The reporter service in this repository: <a href="https://github.com/touidhasan/didlab-trustville/tree/main/services/rain-reporter" target="_blank" rel="noreferrer"><code>services/rain-reporter</code></a></li><li>Read about index-based crop insurance programmes in practice, and look specifically for what farmers say about basis risk.</li></ul><p><strong>Next:</strong> <a href="./15-defi">Module 15 · Swap and lending →</a></p>`,67)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
